import sqlite3, json
path='/home/prop_/.codex/state/1440227652/workflow.sqlite3'
conn=sqlite3.connect('file:{}?mode=ro'.format(path), uri=True)
wid='44ea26aabb36432f92583de22d63c0f3'
last={}
for eid, recorded, raw in conn.execute("select evidence_id,recorded_at,document_json from evidence where workflow_id=? and kind='tdd' order by recorded_at,rowid",(wid,)):
    doc=json.loads(raw)
    curr={i['id']:i.get('status') for i in doc.get('behaviorMap',[]) if 'id' in i}
    for bid,status in curr.items():
        if status=='already-satisfied' and last.get(bid)!='already-satisfied':
            runs=[r for r in doc.get('runs',[]) if r.get('behaviorId')==bid]
            print('\nTRANSITION',recorded,eid,bid,'from',last.get(bid))
            if runs: print(json.dumps(runs[-1],sort_keys=True))
            print('active',doc.get('activeBehaviorId'),'docstatus',doc.get('status'),'command',doc.get('command'))
    last.update(curr)
